import{xt as e}from"./index-CS4Co4Dw.js";async function t(t={}){return(await e.get(`/purchase`,{params:t})).data}async function n(t){return(await e.get(`/purchase/${t}`)).data}async function r(){return(await e.get(`/purchase/next-code`)).data.code}async function i(t){return(await e.get(`/purchase/stock/${t}`)).data.stockQty}async function a(t){return(await e.post(`/purchase`,t)).data}async function o(t,n){return(await e.put(`/purchase/${t}`,n)).data}async function s(t){return(await e.delete(`/purchase/${t}`)).data}export{n as a,r as i,s as n,t as o,i as r,o as s,a as t};